use std::rc::Rc;use std::cell::RefCell;impl Solution{pub fn recover_tree(root:&mut Option<Rc<RefCell<TreeNode>>>){fn vals(n:&Option<Rc<RefCell<TreeNode>>>,v:&mut Vec<Rc<RefCell<TreeNode>>>){if let Some(x)=n{let b=x.borrow();vals(&b.left,v);drop(b);v.push(x.clone());let b=x.borrow();vals(&b.right,v);}}let mut v=vec![];vals(root,&mut v);let(mut a,mut b)=(0,0);for i in 1..v.len(){if v[i-1].borrow().val>v[i].borrow().val{if a==0{a=i}else{b=i}}}if b==0{b=a}let i=a-1;let j=b;let t=v[i].borrow().val;v[i].borrow_mut().val=v[j].borrow().val;v[j].borrow_mut().val=t;}}
